if rtrim(@nguoi_tao) <> ''
BEGIN
SELECT top 0 a.stt_rec into #key from c46$000000 a
DECLARE @q2 NVARCHAR(MAX), @id_nguoi_tao int, @Key NVARCHAR(4000)
SET @Key = ''
select @id_nguoi_tao = id from vsysuserinfo where name = @nguoi_tao
IF @nguoi_tao <> '' SET @Key = @Key + CASE WHEN @Key = '' THEN '' ELSE ' and ' END + '	a.user_id0 like ''' + REPLACE(RTRIM(@id_nguoi_tao), '''', '''''') + '%'''
SET @q2 =' insert into #key select distinct a.stt_rec' 
SET @q2 = @q2 + ' from m51$%Partition a with(nolock)'
SET @q2 = @q2 + ' where %[' + @Key + ']%'
EXEC FastBusiness$Partition$Execute @q2, NULL, 'a.ngay_ct', @ngay_ct1, @ngay_ct2, 1, 1
	SELECT @$detailPartition = '#key'
	SELECt @$detailAlias = 'v'
	SELECT @$detailFilter = '1=1 and a.stt_rec = v.stt_rec'
END

